function money(value: number, compact = false) {
  if (compact && value >= 1000000) return `$${(value / 1000000).toFixed(2)}M`;
  if (compact && value >= 1000) return `$${Math.round(value / 1000)}K`;
  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
}

function useMeta(title: string, description: string) {
  useEffect(() => {
    document.title = `${title} — Northstar Estates`;
    let meta = document.querySelector('meta[name="description"]') as HTMLMetaElement | null;
    if (!meta) { meta = document.createElement('meta'); meta.name = 'description'; document.head.appendChild(meta); }
    meta.content = description;
    let og = document.querySelector('meta[property="og:title"]') as HTMLMetaElement | null;
    if (!og) { og = document.createElement('meta'); og.setAttribute('property', 'og:title'); document.head.appendChild(og); }
    og.content = `${title} — Northstar Estates`;
  }, [title, description]);
}

function Toast({ message, onClose }: { message: string; onClose: () => void }) {
  useEffect(() => { const timer = window.setTimeout(onClose, 3600); return () => window.clearTimeout(timer); }, [onClose]);
  return <div role="status" className="fixed bottom-5 left-1/2 z-[100] flex -translate-x-1/2 items-center gap-3 rounded-full border border-[hsl(var(--accent)/.5)] bg-[hsl(var(--primary))] px-5 py-3 text-sm text-[hsl(var(--primary-foreground))] shadow-xl reveal">
    <span className="grid h-5 w-5 place-items-center rounded-full bg-[hsl(var(--accent))] text-[hsl(var(--primary))]"><Check size={13} strokeWidth={3} /></span>{message}<button aria-label="Dismiss notification" data-testid="button-dismiss-toast" onClick={onClose}><X size={15} /></button>
  </div>;
}

