      {property.tag && <span className="absolute left-4 top-4 rounded-full bg-[hsl(var(--background)/.9)] px-3 py-1.5 text-[9px] font-bold uppercase tracking-[.13em] text-[hsl(var(--primary))]">{property.tag}</span>}
