function LeadModal({ type, onClose, onToast }: { type: 'conversation' | 'showing' | 'valuation' | 'newsletter'; onClose: () => void; onToast: (message: string) => void }) {
  const [sent, setSent] = useState(false);
  const labels = { conversation: ['Begin a conversation', 'Tell us where you are in the process, and we’ll meet you there.'], showing: ['Request a private showing', 'We’ll coordinate a time that respects your schedule.'], valuation: ['Understand your home’s value', 'A thoughtful valuation begins with the story of your property.'], newsletter: ['The Northstar letter', 'A few considered notes on the market, neighborhoods, and the art of living well.'] };
  const [heading, sub] = labels[type];
  function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); setSent(true); window.setTimeout(() => { onClose(); onToast(type === 'newsletter' ? 'You’re on the list. Welcome to the Northstar letter.' : 'Thank you. A Northstar advisor will be in touch shortly.'); }, 900); }
  return <div className="fixed inset-0 z-[90] flex items-end justify-center bg-[hsl(var(--primary)/.6)] p-0 backdrop-blur-sm sm:items-center sm:p-5" role="dialog" aria-modal="true" aria-labelledby="modal-title">
    <div className="relative max-h-[92dvh] w-full max-w-lg overflow-auto bg-[hsl(var(--background))] p-6 shadow-2xl sm:p-10">
      <button onClick={onClose} aria-label="Close form" data-testid="button-close-modal" className="absolute right-5 top-5 rounded-full p-2 hover:bg-[hsl(var(--secondary))]"><X size={18} /></button>
      {sent ? <div className="flex min-h-[280px] flex-col items-center justify-center text-center"><span className="grid h-14 w-14 place-items-center rounded-full bg-[hsl(var(--accent))] text-[hsl(var(--primary))]"><Check size={25} /></span><h2 className="serif mt-6 text-4xl">We’ll be in touch.</h2><p className="mt-3 max-w-sm text-sm leading-6 text-[hsl(var(--muted-foreground))]">Your note is safely with our team. We believe the details matter, and we’ll start there.</p></div> : <><p className="mono text-[hsl(var(--accent-foreground))]">Northstar Estates</p><h2 id="modal-title" className="serif mt-4 text-4xl leading-none text-[hsl(var(--primary))]">{heading}</h2><p className="mt-4 text-sm leading-6 text-[hsl(var(--muted-foreground))]">{sub}</p><form onSubmit={submit} className="mt-7 space-y-4">
        <div className="grid gap-4 sm:grid-cols-2"><label className="text-xs font-semibold">First name<input required name="firstName" data-testid="input-first-name" className="mt-2 w-full border-b border-[hsl(var(--border))] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" placeholder="Your first name" /></label><label className="text-xs font-semibold">Email<input required type="email" name="email" data-testid="input-email" className="mt-2 w-full border-b border-[hsl(var(--border))] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" placeholder="you@email.com" /></label></div>
        {type !== 'newsletter' && <label className="block text-xs font-semibold">I’m looking to…<select name="intent" data-testid="select-intent" className="mt-2 w-full border-b border-[hsl(var(--border))] bg-transparent px-0 py-3 text-sm outline-none"><option>Buy a home</option><option>Sell a home</option><option>Find a rental</option><option>Invest in DFW</option></select></label>}
        {type !== 'newsletter' && <label className="block text-xs font-semibold">A little more context<textarea name="message" data-testid="textarea-message" rows={3} className="mt-2 w-full resize-none border-b border-[hsl(var(--border))] bg-transparent px-0 py-3 text-sm outline-none focus:border-[hsl(var(--primary))]" placeholder="What would be helpful to know?" /></label>}
        <button type="submit" data-testid="button-submit-lead" className="mt-3 flex w-full items-center justify-between rounded-full bg-[hsl(var(--primary))] px-5 py-4 text-xs font-bold uppercase tracking-[.15em] text-[hsl(var(--primary-foreground))] transition hover:bg-[hsl(var(--accent-foreground))]">Send my note <ArrowRight size={17} /></button>
      </form></>}
    </div>
  </div>;
}

